def _request_with_retry(
        self,
        requester,
        *args,
        timeout: Optional[float] = None,
        timeout_message: str = "请求米家服务器超时",
        error_message: str = "请求米家服务器失败",
        **kwargs,
) -> requests.Response:
    timeout = timeout if timeout is not None else self.request_timeout
    last_error: Optional[Exception] = None
    for attempt in range(self.max_retries + 1):
        try:
            return requester(*args, timeout=timeout, **kwargs)
        except requests.exceptions.Timeout as exc:
            last_error = exc
            logger.warning("%s，第 %s 次重试", timeout_message, attempt + 1)
            if attempt >= self.max_retries:
                raise LoginError(-10006, timeout_message)
        except requests.exceptions.RequestException as exc:
            last_error = exc
            logger.warning("%s，第 %s 次重试: %s", error_message, attempt + 1, exc)
            if attempt >= self.max_retries:
                raise LoginError(-10001, f"{error_message}: {exc}")
        time.sleep(self.retry_delay)
    raise LoginError(-10001, f"{error_message}: {last_error}")

