static int aic_de_wait_for_vsync(void)
{
    struct aic_de_comp *comp = aic_de_request_drvdata();
    uint32_t recved;
    int ret;

    event_flag = 1;
    ret = aicos_event_recv(comp->vsync_event,
                           VSYNC_EVENT,
