 */
__ALWAYS_STATIC_INLINE void __DCACHE_CPA(uint32_t addr)
{
#ifdef __riscv_xthead
    __ASM volatile("dcache.cpa %0" : : "r"(addr));
#else
    register unsigned long i asm("a0") = addr;
    asm volatile (".long 0x0295000b"); /* dcache.cpa a0 */
