static void flush_cb(lv_display_t * disp, const lv_area_t * area, uint8_t * color_p)
{
    LV_UNUSED(color_p);
    lv_nuttx_fb_t * dsc = lv_display_get_driver_data(disp);

#if defined(CONFIG_FB_UPDATE)
    if(dsc->update_area_valid) {
        lv_area_join(&dsc->update_area, &dsc->update_area, area);
    }
    else {
        lv_area_copy(&dsc->update_area, area);
        dsc->update_area_valid = true;
    }
#endif

    if(dsc->mem_off_screen) {
        /* When rendering in off-screen mode, copy the drawing buffer to fb */
        /* buf2(off-screen buffer) -> buf1(fbmem)*/
        lv_draw_buf_copy(&dsc->buf1, area, &dsc->buf2, area);
    }

    /* Skip the non-last flush */

    if(!lv_display_flush_is_last(disp)) {
        lv_display_flush_ready(disp);
        return;
    }

#if defined(CONFIG_FB_UPDATE)
    /*May be some direct update command is required*/
    int yoffset = dsc->mem2 != NULL && disp->buf_act != disp->buf_1 ?
                  dsc->mem2_yoffset : 0;

    struct fb_area_s fb_area;
    if(dsc->update_area_valid) {
        fb_area.x = dsc->update_area.x1;
        fb_area.y = dsc->update_area.y1 + yoffset;
        fb_area.w = lv_area_get_width(&dsc->update_area);
        fb_area.h = lv_area_get_height(&dsc->update_area);
        if(ioctl(dsc->fd, FBIO_UPDATE, (unsigned long)((uintptr_t)&fb_area)) < 0) {
            LV_LOG_ERROR("ioctl(FBIO_UPDATE) failed: %d", errno);
        }
        dsc->update_area_valid = false;
    }
#endif

    /* double framebuffer */

    if(dsc->mem2 != NULL) {
        if(disp->buf_act == disp->buf_1) {
            dsc->pinfo.yoffset = 0;
        }
        else {
            dsc->pinfo.yoffset = dsc->mem2_yoffset;
        }

        if(ioctl(dsc->fd, FBIOPAN_DISPLAY, (unsigned long)((uintptr_t) & (dsc->pinfo))) < 0) {
            LV_LOG_ERROR("ioctl(FBIOPAN_DISPLAY) failed: %d", errno);
        }
#if defined(CONFIG_FB_SYNC)
        if(ioctl(dsc->fd, FBIO_WAITFORVSYNC, 0) < 0) {
            LV_LOG_ERROR("ioctl(FBIO_WAITFORVSYNC) failed: %d", errno);
        }
#endif
    }
    lv_display_flush_ready(disp);
}

