    struct fb_planeinfo_s pinfo;

    void * mem;
    void * mem2;
    void * mem_off_screen;
    uint32_t mem2_yoffset;

    lv_draw_buf_t buf1;
    lv_draw_buf_t buf2;
    lv_area_t update_area;
    bool update_area_valid;
} lv_nuttx_fb_t;

