                 page, (unsigned int)lv_tick_elaps(started));
        }
      return;
    }

  g_pages[page] = lv_obj_create(g_page_host);
  lv_obj_remove_style_all(g_pages[page]);
  lv_obj_set_pos(g_pages[page], 0, 0);
