  const struct home_panel_device_s *device, const char *name)
{
  unsigned int index;

  for (index = 0; index < device->control_count; index++)
    {
      if (strcmp(device->controls[index].name, name) == 0)
        {
          return &device->controls[index];
        }
    }

  return NULL;
}

