  lv_obj_set_style_radius(slider, THEME_RADIUS_CTRL, LV_PART_MAIN);
  lv_obj_set_style_radius(slider, THEME_RADIUS_CTRL, LV_PART_INDICATOR);
  lv_obj_set_style_radius(slider, THEME_RADIUS_CTRL, LV_PART_KNOB);
  if (callback != NULL)
