void component_update_toggle(lv_obj_t *toggle, bool checked)
{
  if (toggle == NULL)
    {
      return;
    }

  if (checked)
    {
      lv_obj_add_state(toggle, LV_STATE_CHECKED);
    }
  else
    {
      lv_obj_clear_state(toggle, LV_STATE_CHECKED);
    }
}

