    "AGENT_LLM_STATE_DAILY_LIMIT",
    "AGENT_LLM_STATE_MIN_INTERVAL_SECONDS",
    "AGENT_LLM_PROPOSAL_CONFIDENCE",
}


def _load_private_agent_environment(state_dir: Path) -> bool:
    """Load the cloud advisor configuration from a locked state file."""

    env_path = state_dir / "private" / "agent-llm.env"
    try:
        file_stat = env_path.lstat()
    except FileNotFoundError:
        return False

    if env_path.is_symlink() or not env_path.is_file():
        logger.warning("云端分析配置不是普通文件，已忽略")
        return False
    if file_stat.st_uid != os.geteuid() or file_stat.st_mode & 0o077:
        logger.warning("云端分析配置所有者或权限不安全，已忽略")
        return False
    if file_stat.st_size > 16 * 1024:
        logger.warning("云端分析配置文件过大，已忽略")
        return False

    try:
        lines = env_path.read_text(encoding="utf-8").splitlines()
    except (OSError, UnicodeError):
        logger.warning("云端分析配置读取失败，已忽略")
        return False

    loaded = False
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or "=" not in stripped:
            continue
        key, value = stripped.split("=", 1)
        key = key.strip()
        if key not in AGENT_ENV_KEYS or key in os.environ:
            continue
        value = value.strip()
        if ((value.startswith('"') and value.endswith('"')) or
                (value.startswith("'") and value.endswith("'"))):
            value = value[1:-1]
        if "\x00" in value or "\n" in value or "\r" in value:
            continue
        os.environ[key] = value
        loaded = True
    return loaded


def _bounded_agent_text(value: Any, limit: int) -> str:
    if not isinstance(value, str):
        return ""
    value = re.sub(r"[\x00-\x1f\x7f]", " ", value)
    value = re.sub(r"\s+", " ", value).strip()
    encoded = value.encode("utf-8")
    if len(encoded) <= limit:
        return value
    return encoded[:limit].decode("utf-8", errors="ignore")


def _load_agent_skill(name: str, *, limit: int = 12 * 1024) -> str:
    """Load a repository-owned Skill without following external links."""

    if not re.fullmatch(r"[a-z0-9-]+", name):
        return ""
    path = AGENT_SKILL_ROOT / name / "SKILL.md"
    try:
        if path.is_symlink() or not path.is_file():
            return ""
        raw = path.read_bytes()
    except OSError:
        return ""
    if len(raw) > limit:
        return ""
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        return ""
    if text.startswith("---\n"):
        marker = text.find("\n---\n", 4)
        if marker >= 0:
            text = text[marker + 5:]
    return text.strip()


class AgentCloudAdvisor:
    """Analyze anonymous context without granting the model device access."""

    _ALLOWED_DECISIONS = {"propose", "suppress", "defer"}
    _ALLOWED_POLICIES = {
        "turn_off_selected_light_keep_ac",
        "turn_off_selected_light",
        "execute_local_candidate",
        "notify_only",
        "none",
    }

    def __init__(
        self,
        *,
        base_url: Optional[str] = None,
        api_key: Optional[str] = None,
        model: Optional[str] = None,
        timeout: Optional[float] = None,
        skill_name: str = "d13x-board-ai",
    ):
        self._base_url = (base_url if base_url is not None else
                          os.getenv("AGENT_LLM_BASE_URL", "")).strip()
        self._api_key = (api_key if api_key is not None else
                         os.getenv("AGENT_LLM_API_KEY", "")).strip()
        self._model = (model if model is not None else
                       os.getenv("AGENT_LLM_MODEL", "")).strip()
        configured_timeout = timeout if timeout is not None else float(
            os.getenv("AGENT_LLM_TIMEOUT_SECONDS", "12")
        )
        self._timeout = max(2.0, min(15.0, configured_timeout))
        self._cache: OrderedDict[str, tuple[float, dict[str, Any]]] = OrderedDict()
        self._lock = threading.RLock()
        self._endpoint = self._build_endpoint(self._base_url)
        self._skill_name = skill_name
        self._skill_prompt = _load_agent_skill(skill_name)

    @staticmethod
    def _build_endpoint(base_url: str) -> str:
        if not base_url:
            return ""
        parsed = parse.urlsplit(base_url)
        if parsed.scheme != "https" and parsed.hostname not in {
            "127.0.0.1", "::1", "localhost",
        }:
            return ""
        path = parsed.path.rstrip("/")
        if not path.endswith("/chat/completions"):
            path += "/chat/completions"
        return parse.urlunsplit((parsed.scheme, parsed.netloc, path, "", ""))

    @property
    def configured(self) -> bool:
        return bool(self._endpoint and self._api_key and self._model)

    @property
    def skill_name(self) -> str:
        return self._skill_name

    @property
    def skill_loaded(self) -> bool:
        return bool(self._skill_prompt)

