#!/usr/bin/env python3
"""Exercise the real two-phase proactive protocol without controlling devices."""

import argparse
from pathlib import Path

from mijiaAPI.api_server import (
    AgentCloudAdvisor,
    _agent_normalize_intents,
    _agent_normalize_trigger,
    _agent_normalize_confirmed_plan,
    _agent_normalize_initial_proposal,
    _agent_validate_temporal_evidence,
    _load_private_agent_environment,
)


def build_context() -> dict:
    generated_at = 1786200000
    state = {
        "purpose": "定时同步匿名设备状态，供服务端发现主动智能规律",
        "board_revision": 701,
        "proposal_after": 0,
        "generated_at": generated_at,
        "minute_of_day": 22 * 60 + 12,
        "devices": [
            {
                "device_key": "11111111",
                "room_key": "aaaaaaaa",
                "category": "light",
                "online": True,
                "purpose": "同步灯具状态和可写能力",
                "properties": [{
                    "semantic": "power", "siid": 2, "piid": 1,
                    "value_type": "boolean", "value": True,
                    "writable": True, "minimum": None, "maximum": None,
                    "step": None, "purpose": "同步灯光开关状态",
                }],
            },
            {
                "device_key": "22222222",
                "room_key": "aaaaaaaa",
                "category": "speaker",
                "online": True,
                "purpose": "同步音响状态和可写能力",
                "properties": [{
                    "semantic": "playing", "siid": 3, "piid": 1,
                    "value_type": "boolean", "value": False,
                    "writable": True, "minimum": None, "maximum": None,
                    "step": None, "purpose": "同步音响播放状态",
                }],
            },
            {
                "device_key": "33333333",
                "room_key": "aaaaaaaa",
                "category": "presence-sensor",
                "online": True,
                "purpose": "同步可观测休息状态",
                "properties": [{
                    "semantic": "sleeping", "siid": 4, "piid": 1,
                    "value_type": "boolean", "value": False,
                    "writable": False, "minimum": None, "maximum": None,
                    "step": None, "purpose": "同步可观测休息事件",
                }],
            },
        ],
    }
    events = []
    for day in range(7):
        events.extend([
            {
                "day_index": day + 1,
                "minute_of_day": 22 * 60 + 10,
                "device_key": "11111111", "semantic": "power",
                "previous": True, "value": False,
            },
            {
                "day_index": day + 1,
                "minute_of_day": 22 * 60 + 12,
                "device_key": "22222222", "semantic": "playing",
                "previous": False, "value": True,
            },
            {
                "day_index": day + 1,
                "minute_of_day": 22 * 60 + 40,
                "device_key": "33333333", "semantic": "sleeping",
                "previous": False, "value": True,
            },
            {
                "day_index": day + 1,
                "minute_of_day": 22 * 60 + 47,
                "device_key": "22222222", "semantic": "playing",
                "previous": True, "value": False,
            },
        ])
    return {
        "purpose": "分析七天匿名状态历史并寻找需要用户确认的主动建议",
        "confidence_threshold": 78,
        "latest_state": state,
        "recent_events": events,
    }


def describe_value(value) -> str:
    if value is True:
        return "开启"
    if value is False:
        return "关闭"
    return str(value)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--state-dir", required=True, type=Path)
    args = parser.parse_args()
    if not _load_private_agent_environment(args.state_dir):
        raise SystemExit("private model configuration was not loaded")
    advisor = AgentCloudAdvisor(skill_name="d13x-server-ai")
    if not advisor.configured or not advisor.skill_loaded:
        raise SystemExit("server advisor is not ready")

    context = build_context()
    raw = advisor.analyze_board_state(context)
    proposal = _agent_normalize_initial_proposal(
        raw, context["latest_state"], context["recent_events"]
    )
    if proposal is None:
        print("状态分析：模型结果未通过服务端安全契约，未向板端下发")
        print(f"模型决策：{raw.get('decision', '未知')}")
        print(f"模型置信度：{raw.get('confidence', 0)}%")
        print(f"准备做什么：{raw.get('purpose', '未提供')}")
        print(f"说明：{raw.get('explanation', '未提供')}" )
        if raw.get("decision") == "propose":
            try:
                purpose = raw.get("purpose")
                explanation = raw.get("explanation")
                if not isinstance(purpose, str) or len(purpose.strip()) < 8:
                    raise ValueError("proposal purpose is too short")
                if (not isinstance(explanation, str)
                        or len(explanation.strip()) < 8):
                    raise ValueError("proposal explanation is too short")
                intents = _agent_normalize_intents(
                    raw.get("intents"), context["latest_state"]
                )
                distinct = len({item["device_key"] for item in intents})
                requested_kind = raw.get("proposal_kind")
                is_automation = distinct >= 2 or requested_kind == "automation"
                if not is_automation:
                    raise ValueError("one-time proposal failed an unknown check")
                trigger = _agent_normalize_trigger(
                    raw.get("trigger"), context["latest_state"]
                )
                _agent_validate_temporal_evidence(
                    trigger, intents, context["recent_events"]
                )
                raise ValueError("proposal failed an unknown final check")
            except (KeyError, TypeError, ValueError) as exc:
                print(f"安全校验拒绝原因：{exc}")
                trigger = raw.get("trigger")
                if isinstance(trigger, dict):
                    print(
                        "模型触发器类型：%s（字段：%s）"
                        % (
                            trigger.get("kind", "缺失"),
                            "、".join(sorted(str(key) for key in trigger)),
                        )
                    )
        return 2

    print(f"建议类型：{'多设备自动化' if proposal['kind'] == 'automation' else '仅执行一次'}")
    print(f"置信度：{proposal['confidence']}%")
    print(f"准备做什么：{proposal['purpose']}")
    print(f"判断依据：{proposal['explanation']}")
    trigger = proposal["trigger"]
    if trigger and trigger["kind"] == "time":
        minute = trigger["minute_of_day"]
        print(
            "触发条件：每天 %02d:%02d，允许前后 %d 分钟窗口"
            % (minute // 60, minute % 60, trigger["window_minutes"])
        )
    elif trigger:
        print(
            "触发条件：匿名设备 %s 的 %s 变为 %s，延迟 %d 秒"
            % (
                trigger["device_key"], trigger["semantic"],
                describe_value(trigger["value"]),
                trigger["delay_seconds"],
            )
        )
    for index, intent in enumerate(proposal["intents"], 1):
        print(
            "拟执行动作 %d：%s（匿名设备 %s，%s -> %s）"
            % (
                index, intent["purpose"], intent["device_key"],
                intent["semantic"], describe_value(intent["value"]),
            )
        )
    print("初次分析是否执行：否，必须等待用户确认")

    if proposal["kind"] == "automation":
        material = {
            "request_purpose": "测试用户同意后生成可离线保存的自动化 JSON",
            "consented_purpose": proposal["purpose"],
            "consented_explanation": proposal["explanation"],
            "consented_trigger": proposal["trigger"],
            "consented_intents": proposal["intents"],
        }
        raw_plan = advisor.generate_confirmed_automation(material)
        plan = _agent_normalize_confirmed_plan(
            raw_plan, proposal, context["latest_state"]
        )
        print("模拟用户确认后的二次生成：通过")
        print(f"最终动作数：{len(plan['actions'])}，未增加或改写设备动作")
        print("板端处理：收到后再次校验，执行并保存为离线自动化")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

