#ifdef CONFIG_MBEDTLS_ENTROPY_HARDWARE_ALT
int mbedtls_hardware_poll(FAR void *data,
                          FAR unsigned char *output,
                          size_t len,
                          FAR size_t *olen)
{
  int fd;
  size_t read_len;
  *olen = 0;

  fd = open("/dev/random", O_RDONLY, 0);
  if (fd < 0)
    {
      return -errno;
    }

  read_len = read(fd, output, len);
  if (read_len != len)
    {
      close(fd);
      return -errno;
    }

  close(fd);
  *olen = len;

  return 0;
}
