      if (chunk > sizeof(g_trng_output))
        {
          chunk = sizeof(g_trng_output);
        }

      memset(&g_trng_task, 0, sizeof(g_trng_task));
      memset(g_trng_output, 0, sizeof(g_trng_output));
      g_trng_task.words[0] = D13X_CE_TRNG_TAG;
      /* TRNG has no input stream; only the 256-bit output is described. */
      g_trng_task.words[9] = 0x3u;
      g_trng_task.words[13] = (uint32_t)(uintptr_t)g_trng_output;
      g_trng_task.words[14] = sizeof(g_trng_output);
      up_flush_dcache((uintptr_t)&g_trng_task,
                      (uintptr_t)&g_trng_task + sizeof(g_trng_task));
      up_flush_dcache((uintptr_t)g_trng_output,
                      (uintptr_t)g_trng_output + sizeof(g_trng_output));

