static bool d13x_tls_conn_alive(int fd)
{
  char probe;
  ssize_t r = recv(fd, &probe, 1, MSG_PEEK | MSG_DONTWAIT);

  if (r == 0)
    {
      return false;
    }

  if (r < 0)
    {
      return errno == EAGAIN || errno == EWOULDBLOCK;
    }

  return false;
}

