          g_conn_pool = conn;
          strncpy(g_conn_pool_host, conn->host, sizeof(g_conn_pool_host) - 1);
          g_conn_pool_host[sizeof(g_conn_pool_host) - 1] = '\0';
          g_conn_pool_port = conn->port;
          pthread_mutex_unlock(&g_conn_pool_lock);
          return 0;
        }

      pthread_mutex_unlock(&g_conn_pool_lock);
    }

  d13x_tls_conn_free(conn);
  return 0;
}

