#!/usr/bin/env python3
"""Export opencode/mimocode SQLite sessions into the contest logs/ layout.

Only sessions whose directory is inside the OpenVela/D13x workspace are
exported, automatic checkpoint-writer sessions and sessions already present
in logs/ are skipped, and MiMo Code sessions are recorded with tool=opencode
as agreed with the contest organisers.
"""
from __future__ import annotations

import datetime
import json
import re
import sqlite3
import sys
from pathlib import Path

REPO = Path("/home/lladlam/OpenVela/contest2026_011_ladelamuStudio")
LOGS = REPO / "logs" / "lladlam"
TEAM = "contest2026_011_ladelamuStudio"
LOGIN = "lladlam"
DRY = "--dry-run" in sys.argv

DBS = [
    ("opencode", "/home/lladlam/.local/share/opencode/opencode.db"),
    ("mimocode", "/home/lladlam/.local/share/mimocode/mimocode.db"),
]

REDACT = [
    (re.compile(r"sk-[A-Za-z0-9_-]{20,}"), "sk-***REDACTED***"),
    (re.compile(r"ghp_[A-Za-z0-9]{36}"), "ghp_***REDACTED***"),
    (re.compile(r"Bearer\s+[A-Za-z0-9._\-+/=]+"), "Bearer ***REDACTED***"),
]

SKIP_PARTS = {"step-start", "step-finish", "step", "patch", "snapshot",
              "agent", "retry", "compaction", "subtask"}


def redact(value):
    if isinstance(value, str):
        for pat, rep in REDACT:
            value = pat.sub(rep, value)
        return value
    if isinstance(value, list):
        return [redact(v) for v in value]
    if isinstance(value, dict):
        return {k: redact(v) for k, v in value.items()}
    return value


def existing_ids():
    ids = set()
    for f in LOGS.glob("*/*.jsonl"):
        try:
            with open(f, encoding="utf-8") as fh:
                first = fh.readline()
            e = json.loads(first)
            sid = e.get("session_id")
            if sid:
                ids.add(sid)
        except Exception:
            pass
    return ids


def iso(ms):
    return (datetime.datetime.fromtimestamp(ms / 1000, datetime.timezone.utc)
            .isoformat().replace("+00:00", "Z"))


def local_date(ms):
    d = datetime.datetime.fromtimestamp(ms / 1000)
    return f"{d.year:04d}-{d.month:02d}-{d.day:02d}"


def model_of(md):
    m = md.get("model")
    if isinstance(m, str):
        return m
    if isinstance(m, dict):
        p = m.get("providerID") or m.get("provider") or ""
        i = m.get("modelID") or m.get("id") or ""
        return f"{p}/{i}" if p and i else (i or p or None)
    p = md.get("providerID") or ""
    i = md.get("modelID") or ""
    return f"{p}/{i}" if p and i else (i or p or None)


def session_events(conn, sid):
    parts = {}
    for mid, pdata in conn.execute(
            "select message_id, data from part where session_id=? "
            "order by time_created, id", (sid,)):
        parts.setdefault(mid, []).append(pdata)

    events = []
    for mid, mtc, mdata in conn.execute(
            "select id, time_created, data from message where session_id=? "
            "order by time_created, id", (sid,)):
        md = json.loads(mdata)
        role = (md.get("role") or "").lower()
        if role not in ("user", "assistant", "system"):
            continue
        base = (md.get("time") or {}).get("created") or mtc
        model = model_of(md)
        tokens = md.get("tokens") or {}

        for pdata in parts.get(mid, []):
            pd = json.loads(pdata)
            ptype = pd.get("type")
            if ptype in SKIP_PARTS:
                continue
            ts = iso((pd.get("time") or {}).get("start") or base)

            if ptype == "text":
                text = pd.get("text") or ""
                if not text.strip():
                    continue
                ev = {"role": role, "ts": ts, "text": redact(text)}
                if model:
                    ev["model"] = model
                if role == "assistant":
                    if isinstance(tokens.get("input"), int):
                        ev["tokens_in"] = tokens["input"]
                    if isinstance(tokens.get("output"), int):
                        ev["tokens_out"] = tokens["output"]
                events.append(ev)
            elif ptype in ("reasoning", "thinking"):
                text = pd.get("text") or pd.get("content") or ""
                if not text.strip():
                    continue
                ev = {"role": role, "ts": ts, "thinking": redact(text)}
                if model:
                    ev["model"] = model
                events.append(ev)
            elif ptype in ("tool", "tool-invocation"):
                state = pd.get("state") or {}
                if not isinstance(state, dict):
                    state = {}
                ev = {
                    "role": "tool",
                    "ts": ts,
                    "tool_name": pd.get("tool") or "tool",
                    "tool_call_id": pd.get("callID") or pd.get("callId") or mid,
                    "input": redact(state.get("input")),
                    "output": redact(state.get("output")),
                }
                meta = state.get("metadata")
                if isinstance(meta, dict) and meta:
                    ev["metadata"] = redact(meta)
                events.append(ev)

    for seq, ev in enumerate(events):
        ev["seq"] = seq
    return events


def main():
    known = existing_ids()
    written = skipped = 0
    total_events = 0
    total_bytes = 0

    for name, db in DBS:
        conn = sqlite3.connect(f"file:{db}?mode=ro", uri=True, timeout=120)
        rows = list(conn.execute(
            "select id, directory, title, time_created from session"))
        for sid, directory, title, tc in rows:
            if not directory or ("/OpenVela" not in directory
                                 and "/D13x" not in directory):
                continue
            if (title or "").lower().startswith("checkpoint-writer"):
                continue
            if sid in known:
                skipped += 1
                continue
            events = session_events(conn, sid)
            if not events:
                skipped += 1
                continue
            for ev in events:
                ev.update({
                    "schema_version": "1.0",
                    "session_id": sid,
                    "team_id": TEAM,
                    "github_login": LOGIN,
                    "tool": "opencode",
                })
            order = ["schema_version", "session_id", "team_id",
                     "github_login", "tool", "seq", "role", "ts"]
            lines = []
            for ev in events:
                ordered = {k: ev[k] for k in order if k in ev}
                ordered.update({k: v for k, v in ev.items()
                                if k not in ordered})
                lines.append(json.dumps(ordered, ensure_ascii=False))
            payload = "\n".join(lines) + "\n"
            total_events += len(lines)
            total_bytes += len(payload.encode("utf-8"))
            written += 1

            day = local_date(tc)
            out = LOGS / day / f"opencode__{sid}.jsonl"
            if DRY:
                print(f"  [dry] {name:8s} {day} {sid[:26]} "
                      f"events={len(lines):5d} {len(payload)/1e6:7.2f}MB")
            else:
                out.parent.mkdir(parents=True, exist_ok=True)
                out.write_text(payload, encoding="utf-8")
                print(f"  wrote {day}/opencode__{sid[:26]} "
                      f"events={len(lines)} {len(payload)/1e6:.2f}MB")

    print(f"\n{'DRY RUN: ' if DRY else ''}sessions={written} "
          f"skipped={skipped} events={total_events} "
          f"bytes={total_bytes/1e6:.1f}MB")


if __name__ == "__main__":
    main()
